<?php $pageTitle='Matches';require_once dirname(__DIR__).'/includes/header.php';require_once dirname(__DIR__).'/includes/auth.php';require_auth(['super_admin','admin']);$t=active_tournament($pdo);$tid=(int)($t['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf($_POST['csrf_token']??null);$id=(int)$_POST['id'];$pdo->prepare('UPDATE matches SET scheduled_at=?,court=?,assigned_judge_id=? WHERE id=? AND tournament_id=?')->execute([$_POST['scheduled_at']?:null,trim($_POST['court']??''),$_POST['assigned_judge_id']?:null,$id,$tid]);audit_log($pdo,'schedule','match',$id,'Updated match schedule');header('Location: matches.php?saved=1');exit;}catch(Throwable $e){$error=$e->getMessage();}}
$judges=$pdo->query("SELECT id,name FROM users WHERE role IN ('judge','admin','super_admin') ORDER BY name")->fetchAll();$s=$pdo->prepare("SELECT m.*,p1.name p1_name,p2.name p2_name,u.name judge_name FROM matches m LEFT JOIN participants p1 ON p1.id=m.participant1_id LEFT JOIN participants p2 ON p2.id=m.participant2_id LEFT JOIN users u ON u.id=m.assigned_judge_id WHERE m.tournament_id=? ORDER BY round_number,match_number");$s->execute([$tid]);require dirname(__DIR__).'/includes/sidebar.php';?>
<div class="toolbar"><div><div class="eyebrow">Schedule control</div><h2 style="margin:4px 0">All matches</h2></div><a class="btn btn-primary" href="scoring.php"><i class="fa-solid fa-stopwatch"></i> Open Scoring</a></div><div class="table-wrap"><table><thead><tr><th>Match</th><th>Round</th><th>Score</th><th>Schedule / Court / Judge</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($s->fetchAll() as $m):?><tr><td><strong><?=e($m['p1_name']??'TBD')?></strong><br><span style="color:var(--text-secondary)">vs <?=e($m['p2_name']??'TBD')?></span></td><td><?=e($m['round'])?> #<?=$m['match_number']?></td><td><?=$m['score1']?> : <?=$m['score2']?></td><td><form method="post" style="display:grid;gap:6px;min-width:210px"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$m['id']?>"><input type="datetime-local" name="scheduled_at" value="<?=$m['scheduled_at']?date('Y-m-d\TH:i',strtotime($m['scheduled_at'])):''?>"><input name="court" value="<?=e($m['court'])?>" placeholder="Court"><select name="assigned_judge_id"><option value="">Unassigned judge</option><?php foreach($judges as $j):?><option value="<?=$j['id']?>" <?=$m['assigned_judge_id']==$j['id']?'selected':''?>><?=e($j['name'])?></option><?php endforeach;?></select><button class="btn btn-sm">Save Schedule</button></form></td><td><span class="badge <?=e($m['status'])?>"><?=e($m['status'])?></span></td><td><a class="btn btn-sm" href="scoring.php?match_id=<?=$m['id']?>">Score</a></td></tr><?php endforeach;?></tbody></table></div>
